def orbit(deg, c):
    a = math.radians(deg)
    pts = [(170 + 62 * math.cos(t) * math.cos(a) - 18 * math.sin(t) * math.sin(a), 100 + 62 * math.cos(t) * math.sin(a) + 18 * math.sin(t) * math.cos(a))
           for t in (2 * math.pi * i / 14 for i in range(15))]
    return [line(round(x1), round(y1), round(x2), round(y2), 3, c) for (x1, y1), (x2, y2) in zip(pts, pts[1:])]


def dashed_star():
    pts = star(170, 100, 54, 22, 5, IN)[0]
    out = []
    for (x1, y1), (x2, y2) in zip(pts, pts[1:] + pts[:1]):
        for a, b in ((0, 0.4), (0.6, 1)):
            out.append(line(round(x1 + (x2 - x1) * a), round(y1 + (y2 - y1) * a), round(x1 + (x2 - x1) * b), round(y1 + (y2 - y1) * b), 4, IN))
    return out


def burst(cx, cy, r, c):
    return [line(round(cx + 8 * math.cos(a)), round(cy + 8 * math.sin(a)), round(cx + r * math.cos(a)), round(cy + r * math.sin(a)), 3, c)
            for a in (math.pi * i / 4 for i in range(8))] + [O(cx, cy, 4, 4, c)]


def cone(x):
    return [P([(x - 14, 150), (x - 4, 100), (x + 4, 100), (x + 14, 150)], OR), R(x - 9, 120, 18, 6, CR), R(x - 18, 150, 36, 6, OR)]


def sack(cx, cy):
    return [O(cx, cy, 24, 28, SB, 12), R(cx - 6, cy - 32, 12, 8, BR)]


